import{randomUUID}from"node:crypto";import{mkdir,writeFile}from"node:fs/promises";import{chromium}from"@playwright/test";
export default async function(){const runId=`${Date.now().toString(36)}-${randomUUID().slice(0,8)}`;process.env.COMUN_TEST_RUN_ID=runId;const fixtures=await import("./operational-personas.mjs");await fixtures.cleanupOperationalPersonas();const manifest=await fixtures.createOperationalPersonas();const root=`.local/comun-auth/${runId}`;await mkdir(root,{recursive:true});const browser=await chromium.launch();try{for(const entry of manifest){const context=await browser.newContext();const page=await context.newPage();const redirect="/comun/admin";await page.goto(`${process.env.COMUN_BASE_URL??"http://127.0.0.1:3000"}/comun/admin/login?redirectTo=${encodeURIComponent(redirect)}`);await page.getByLabel("E-mail").fill(entry.email);await page.getByLabel("Senha").fill(fixtures.operationalPassword);await page.getByRole("button",{name:"Entrar"}).click();if(entry.persona!=="participant"&&!new URL(page.url()).pathname.startsWith("/comun/admin"))throw new Error(`storageState inválido: ${entry.persona}`);const path=`${root}/${entry.persona}.json`;await context.storageState({path});await context.close()}}finally{await browser.close()}await writeFile(".local/comun-auth/current.json",JSON.stringify({runId,generatedAt:new Date().toISOString(),personas:manifest.map(({persona,email,user})=>({persona,email,userId:user.id,state:`${root}/${persona}.json`}))},null,2)+"\n")}
